    16→import static com.google.common.base.Preconditions.checkArgument;
    17→import static org.apache.commons.lang3.StringUtils.isMixedCase;
    18→
    19→import java.nio.charset.StandardCharsets;
    20→import java.util.Locale;
    21→import org.apache.tuweni.bytes.Bytes;
    22→import tech.pegasys.teku.infrastructure.bytes.Bytes20;
