    25→
    26→public class Eth1Address extends Bytes20 {
    27→  public static final DeserializableTypeDefinition<Eth1Address> ETH1ADDRESS_TYPE =
    28→      DeserializableTypeDefinition.string(Eth1Address.class)
    29→          .formatter(Eth1Address::toHexString)
    30→          .parser(Eth1Address::fromHexString)
    31→          .example("0x1Db3439a222C519ab44bb1144fC28167b4Fa6EE6")
    32→          .description("Hex encoded deposit contract address with 0x prefix")
    33→          .format("byte")
    34→          .build();
    35→  private static final String ZERO_ADDRESS_STRING = "0x0000000000000000000000000000000000000000";
    36→  private static final int HEX_ADDRESS_STRING_LENGTH = ZERO_ADDRESS_STRING.length();
    37→
    38→  public static final Eth1Address ZERO = new Eth1Address(ZERO_ADDRESS_STRING);
    39→
    40→  private final String encodedAddress;
    41→
    42→  private Eth1Address(final String value) {
    43→    super(Bytes.fromHexString(value));
    44→    String valueWithPrefix = value;
    45→    if (!value.startsWith("0x")) {
    46→      valueWithPrefix = "0x" + value;
    47→    }
    48→    this.encodedAddress = toChecksumAddress(valueWithPrefix);
    49→    validate(valueWithPrefix);
    50→  }
    51→
    52→  private Eth1Address(final Bytes bytes) {
    53→    super(bytes);
    54→    final String value = bytes.toHexString();
    55→    this.encodedAddress = toChecksumAddress(value);
    56→    validate(value);
    57→  }
    58→
    59→  private void validate(final String value) {
    60→    if (isMixedCase(value.substring("0x".length()))) {
    61→      checkArgument(
    62→          value.equals(encodedAddress),
    63→          "Eth1Address fails checksum:\n got: %s\n exp: %s",
    64→          value,
    65→          encodedAddress);
    66→    }
    67→  }
    68→
    69→  public static Eth1Address fromBytes(final Bytes value) {
    70→    return new Eth1Address(value);
    71→  }
    72→
    73→  public static Eth1Address fromHexString(final String value) {
    74→    try {
    75→      return new Eth1Address(value);
    76→    } catch (RuntimeException ex) {
    77→      throw new IllegalArgumentException("Invalid Ethereum Address: " + ex.getMessage(), ex);
    78→    }
    79→  }
    80→
    81→  /**
    82→   * Produce an address with a mixed-case checksum as defined by <a
    83→   * href="https://eips.ethereum.org/EIPS/eip-55">EIP-55</a>.
    84→   *
    85→   * @param value The string representation of an Ethereum address.
    86→   * @return The encoded address with mixed-case checksum.
    87→   */
    88→  private static String toChecksumAddress(final String value) {
    89→    final String address = value.replace("0x", "").toLowerCase(Locale.ROOT);
    90→    final String hashString =
    91→        Hash.keccak256(Bytes.wrap(address.getBytes(StandardCharsets.US_ASCII)))
    92→            .toString()
    93→            .replace("0x", "");
    94→    final StringBuilder ret = new StringBuilder(HEX_ADDRESS_STRING_LENGTH).append("0x");
    95→    for (int i = 0; i < address.length(); i++) {
    96→      final String letter = String.valueOf(hashString.charAt(i));
    97→      if (Integer.parseInt(letter, 16) >= 8) {
    98→        ret.append(Character.toUpperCase(address.charAt(i)));
    99→      } else {
   100→        ret.append(address.charAt(i));
   101→      }
   102→    }
   103→    return ret.toString();
   104→  }
   105→
   106→  @Override
   107→  public String toString() {
   108→    return encodedAddress;
   109→  }
   110→
   111→  @Override
   112→  public String toHexString() {
   113→    return encodedAddress;
   114→  }
   115→
   116→  @Override
   117→  public String toUnprefixedHexString() {
   118→    return encodedAddress.substring(2);
   119→  }
   120→}
